import numpy as np, re, requests, json
import matplotlib.pyplot as plt

ACC={"Tsr":"P02942","McpB":"P39215","McpC":"P54576","McpA":"P39214"}
S={k:"".join(requests.get(f"https://rest.uniprot.org/uniprotkb/{a}.fasta",timeout=30).text.strip().split("\n")[1:]) for k,a in ACC.items()}
tipp={k:re.search(r"G[FLIV][ASG]VVA[DEG]EVR",s).start()+1 for k,s in S.items()}

# ---------- UniProt topology features: where does the cytoplasmic hairpin start? ----------
print("--- UniProt TRANSMEM / DOMAIN features ---")
TM2={}
for k,a in ACC.items():
    j=requests.get(f"https://rest.uniprot.org/uniprotkb/{a}?fields=ft_transmem,ft_domain,length",timeout=30).json()
    feats=[(f["type"],f["location"]["start"]["value"],f["location"]["end"]["value"],f.get("description",""))
           for f in j.get("features",[]) if f["type"] in ("Transmembrane","Domain")]
    print(f"  {k} ({a}, len {j['sequence']['length']}): "+ "; ".join(f"{t} {s}-{e} {d}" for t,s,e,d in feats))
    tms=[(s,e) for t,s,e,d in feats if t=="Transmembrane"]
    TM2[k]=max(e for s,e in tms) if tms else None

print("\n--- hairpin arm length, tip anchor minus last TM residue ---")
for k in ACC:
    print(f"  {k}: tip {tipp[k]}, last TM residue {TM2[k]}, arm {tipp[k]-TM2[k]} residues = {(tipp[k]-TM2[k])/7:.1f} heptads")

# ---------- axial position of each candidate site along the hairpin ----------
def read_atoms(path, chain=None):
    ca={}; cb={}
    for l in open(path):
        if not l.startswith("ATOM") or l[16] not in (" ","A"): continue
        if chain and l[21]!=chain: continue
        n=l[12:16].strip(); r=int(l[22:26]); xyz=np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])])
        if n=="CA": ca[r]=xyz
        elif n=="CB": cb[r]=xyz
    return ca,cb

MOD={"Tsr":"tsr_af.pdb","McpB":"mcpB_af.pdb","McpC":"mcpC_af.pdb","McpA":"mcpA_af.pdb"}
SITES={"Tsr":[(297,"Q297 d"),(304,"E304"),(311,"Q311 d"),(493,"E493"),(502,"E502")],
       "McpB":[(371,"Q371"),(595,"Q595"),(630,"E630"),(637,"E637")],
       "McpC":[(609,"Q609 CheD")],
       "McpA":[(377,"Q377"),(391,"Q391"),(615,"E615")]}

res={}
fig,axes=plt.subplots(1,4,figsize=(17,6),sharey=True)
for ax,k in zip(axes,["Tsr","McpB","McpC","McpA"]):
    ca,cb=read_atoms(MOD[k])
    lo,hi=TM2[k]+1,max(ca)                      # cytoplasmic region
    idx=[r for r in sorted(ca) if lo<=r<=hi]
    X=np.array([ca[r] for r in idx])
    Xc=X-X.mean(0); u=np.linalg.svd(Xc,full_matrices=False)[2][0]   # bundle long axis
    z={r:float((ca[r]-ca[tipp[k]])@u) for r in idx}
    if np.mean([z[r] for r in idx[:20]])<0: u=-u; z={r:-v for r,v in z.items()}   # tip at 0, membrane positive
    rad={r:float(np.linalg.norm((ca[r]-ca[tipp[k]]) - z[r]*u)) for r in idx}
    res[k]=(z,rad,idx)
    ax.plot([z[r] for r in idx],[rad[r] for r in idx],lw=0.6,color="0.75")
    for p,lab in SITES[k]:
        if p in z:
            ax.plot(z[p],rad[p],"o",ms=9,color="crimson" if "d" in lab or k!="Tsr" else "steelblue")
            ax.annotate(lab,(z[p],rad[p]),textcoords="offset points",xytext=(4,6),fontsize=9)
    ax.axvline(0,color="k",ls=":",lw=1); ax.set_title(f"{k}, arm {tipp[k]-TM2[k]} res")
    ax.set_xlabel("axial distance from hairpin tip (A)")
axes[0].set_ylabel("radial distance from bundle axis (A)")
fig.suptitle("Axial position of claimed modification sites along the chemoreceptor cytoplasmic hairpin (AlphaFold models)")
plt.tight_layout(); plt.show()

print("\n--- axial distance from tip (Angstrom) and from the last TM residue ---")
for k in ["Tsr","McpB","McpC","McpA"]:
    z,rad,idx=res[k]
    zTM=z[TM2[k]+1]
    for p,lab in SITES[k]:
        if p in z:
            print(f"  {k:5s} {lab:10s} pos {p}: z_tip {z[p]:7.1f} A, z_from_TM {zTM-z[p]:7.1f} A, "
                  f"residues from TM {p-TM2[k]:4d}, residues from tip {tipp[k]-p if p<tipp[k] else p-tipp[k]:4d}")
